def tri_selection(L):
    for i in range(len(L)):
        j_min = i
        for j in range(i + 1, len(L)):
            if L[j] < L[j_min]:
                j_min = j
        L[i], L[j_min] = L[j_min], L[i]
    return L

print(tri_selection([5, 3, 8, 1, 9, 2]))

import random

def frequence_de_six(n):
    """Fréquence d'apparition du 6 sur n lancers d'un dé équilibré."""
    compteur = 0
    for i in range(n):
        if random.randint(1, 6) == 6:
            compteur = compteur + 1
    return compteur / n

def rectangles(n):
    """Somme des aires des n rectangles à gauche sur [0 ; 1]."""
    aire = 0
    for k in range(n):
        aire = aire + (k / n)**2 * (1 / n)
    return aire

for n in [4, 10, 100, 1000]:
    print(n, rectangles(n))
